    { id = 7642, name = "Collection of Goods", level = 60, minLevel = 60, requires = { 7641 }, races = 5, giver = "Grimand Elmore", start = { npc = "Grimand Elmore", area = 1519, x = 51.8, y = 12.1 }, finish = { npc = "Grimand Elmore", area = 1519, x = 51.8, y = 12.1 }, objective = "Bring 40 Runecloth, 6 Arcanite Bars, 10 Arthas' Tears, 5 Stratholme Holy Water vials, and 150 gold to Grimand Elmore in the Dwarven District of Stormwind." },
    { id = 7643, name = "Ancient Equine Spirit", level = 60, minLevel = 60, requires = { 7642 }, races = 5, giver = "Lord Grayson Shadowbreaker", start = { npc = "Lord Grayson Shadowbreaker", area = 1519, x = 37.2, y = 33.3 }, finish = { npc = "Ancient Equine Spirit" }, objective = "Acquire special horse feed used for feeding a spirit horse. Merideth Carlson in Southshore apparently is the source for such food.  Travel to the Dire Maul dungeon in Feralas and slay Tendris Warpwood. Doing so will free the Ancient Equine Spirit. Feed it the special horse feed, thereby soothing the spirit. Finally, give it the Arcanite Barding so it may bless it." },
    { id = 7644, name = "Blessed Arcanite Barding", level = 60, minLevel = 60, requires = { 7643 }, races = 5, giver = "Ancient Equine Spirit", start = { npc = "Ancient Equine Spirit" }, finish = { npc = "Lord Grayson Shadowbreaker", area = 1519, x = 37.2, y = 33.3 }, objective = "Return with the Blessed Arcanite Barding to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind." },
    { id = 7645, name = "Manna-Enriched Horse Feed", level = 60, minLevel = 60, races = 5, giver = "Merideth Carlson", start = { npc = "Merideth Carlson", area = 267, x = 52.2, y = 55.5 }, finish = { npc = "Merideth Carlson", area = 267, x = 52.2, y = 55.5 }, objective = "Retrieve 20 Enriched Manna Biscuits - the key ingredient in making Manna-Enriched Horse Feed - for Merideth Carlson at Southshore in the Hillsbrad Foothills. The Argent Dawn is known as the sole purveyor of the biscuits.  You also need to give her 50 gold to soothe her ruffled sensibilities." },
    { id = 7646, name = "The Divination Scryer", level = 60, minLevel = 60, requires = { 7644 }, races = 5, giver = "Lord Grayson Shadowbreaker", start = { npc = "Lord Grayson Shadowbreaker", area = 1519, x = 37.2, y = 33.3 }, finish = { npc = "Lord Grayson Shadowbreaker", area = 1519, x = 37.2, y = 33.3 }, objective = "Bring an Azerothian Diamond and a Pristine Black Diamond to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind." },
    { id = 7647, name = "Judgment and Redemption", level = 60, minLevel = 60, requires = { 7646 }, races = 5, giver = "Lord Grayson Shadowbreaker", start = { npc = "Lord Grayson Shadowbreaker", area = 1519, x = 37.2, y = 33.3 }, finish = { npc = "Darkreaver's Fallen Charger" }, objective = "Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance. Doing so will bring forth the spirits you must judge. Defeating these spirits will summon forth Death Knight Darkreaver. Defeat him and reclaim the lost soul of the fallen charger.  Give the Charger's Redeemed Soul and the Blessed Enchanted Barding to Darkreaver's Fallen Charger." },
