    { id = 2380, name = "To Orgrimmar!", level = 16, minLevel = 16, faction = "Horde", giver = "Kaplak", start = { npc = "Kaplak", area = 14, x = 52.0, y = 43.7 }, finish = { npc = "Shenthul", area = 1637, x = 43.0, y = 53.7 }, objective = "Speak with Shenthul at the Cleft of Shadow in Orgrimmar." },
    { id = 2381, name = "Plundering the Plunderers", level = 18, minLevel = 16, requires = { 2382 }, faction = "Horde", giver = "Wrenix the Wretched", start = { npc = "Wrenix the Wretched", area = 17, x = 63.1, y = 36.3 }, finish = { npc = "Wrenix the Wretched", area = 17, x = 63.1, y = 36.3 }, objective = "Bring the Southsea Treasure back to Wrenix the Wretched in Ratchet. Do not forget to get an E.C.A.C. and Thieves' Tools from Wrenix's Gizmotronic Apparatus. You will need both of these items to complete your mission.  Should you be attacked by any unusually hostile parrots, use your E.C.A.C.!" },
    { id = 2382, name = "Wrenix of Ratchet", level = 16, minLevel = 16, requires = { 2379 }, faction = "Horde", giver = "Zando'zan", start = { npc = "Zando'zan", area = 1637, x = 42.7, y = 53.0 }, finish = { npc = "Wrenix the Wretched", area = 17, x = 63.1, y = 36.3 }, objective = "Travel to Ratchet and speak with Wrenix the Wretched." },
    { id = 2458, name = "Deep Cover", level = 20, minLevel = 20, requires = { 2460 }, faction = "Horde", giver = "Shenthul", start = { npc = "Shenthul", area = 1637, x = 43.0, y = 53.7 }, finish = { npc = "Taskmaster Fizzule", area = 17, x = 55.4, y = 5.6 }, objective = "Travel to the Venture Co. Tower, north of the Sludge Fen and contact the Shattered Hand's covert operative, Taskmaster Fizzule.  When the tower is in sight, use the Flare Gun to signal your arrival to Taskmaster Fizzule. Fire off TWO flares, then approach Taskmaster Fizzule and perform the Shattered /Salute.  These actions must be performed in the correct order, as Fizzule will attack and terminate any person he does not recognize." },
    { id = 2460, name = "The Shattered Salute", level = 20, minLevel = 20, faction = "Horde", giver = "Shenthul", start = { npc = "Shenthul", area = 1637, x = 43.0, y = 53.7 }, finish = { npc = "Shenthul", area = 1637, x = 43.0, y = 53.7 }, objective = "Perform the Shattered Salute on Shenthul." },
    { id = 2478, name = "Mission: Possible But Not Probable", level = 24, minLevel = 20, requires = { 2458 }, faction = "Horde", giver = "Taskmaster Fizzule", start = { npc = "Taskmaster Fizzule", area = 17, x = 55.4, y = 5.6 }, finish = { npc = "Shenthul", area = 1637, x = 43.0, y = 53.7 }, objective = "Steal Silixiz's Tower Key from Foreman Silixiz, then kill two Mutated Venture Co. Drones, two Venture Co. Patrollers, and two Venture Co. Lookouts.  Assassinate Grand Foreman Gallywix and take his head, then pick the lock on Gallywix's lockbox and steal the Cache of Zanzil's Altered Mixture. Take the Cache and Gallywix's Head back to Shenthul in Orgrimmar for further instruction. " },
    { id = 2479, name = "Hinott's Assistance (1/2)", level = 26, minLevel = 20, requires = { 2478 }, faction = "Horde", giver = "Shenthul", start = { npc = "Shenthul", area = 1637, x = 43.0, y = 53.7 }, finish = { npc = "Serge Hinott", area = 267, x = 61.6, y = 19.2 }, objective = "Travel to Tarren Mill in Hillsbrad Foothills and deliver the Sample of Zanzil's Mixture to Serge Hinott.  To get to Tarren Mill, take the Zeppelin to the Undercity and follow the road south through Silverpine and towards Hillsbrad. Follow the signs!  " },
    { id = 2480, name = "Hinott's Assistance (2/2)", level = 20, minLevel = 20, requires = { 2479 }, faction = "Horde", giver = "Serge Hinott", start = { npc = "Serge Hinott", area = 267, x = 61.6, y = 19.2 }, finish = { npc = "Serge Hinott", area = 267, x = 61.6, y = 19.2 }, objective = "Wait for Serge Hinott to complete the cure." },
    { id = 2607, name = "The Touch of Zanzil (1/3)", level = 20, minLevel = 20, requires = { 2359 }, faction = "Alliance", giver = "Master Mathias Shaw", start = { npc = "Master Mathias Shaw", area = 1519, x = 75.8, y = 59.8 }, finish = { npc = "Doc Mixilpixil", area = 1519, x = 78.0, y = 58.8 }, objective = "Speak with Doc Mixilpixil in the cellar of the Barracks." },
    { id = 2608, name = "The Touch of Zanzil (2/3)", level = 20, minLevel = 20, requires = { 2607 }, faction = "Alliance", giver = "Doc Mixilpixil", start = { npc = "Doc Mixilpixil", area = 1519, x = 78.0, y = 58.8 }, finish = { npc = "Doc Mixilpixil", area = 1519, x = 78.0, y = 58.8 }, objective = "/Lay down to be examined by Doc Mixilpixil. How can he find the cure if he can't find the cause? " },
