    { id = 7581, name = "The Prison's Bindings", level = 60, minLevel = 60, giver = "Daio the Decrepit", start = { npc = "Daio the Decrepit", area = 4, x = 34.1, y = 50.1 }, finish = { npc = "Daio the Decrepit", area = 4, x = 34.1, y = 50.1 }, objective = "Travel to Dire Maul in Feralas and recover 15 Satyr Blood from the Wildspawn Satyr that inhabit the Warpwood Quarter. Return to Daio in the Tainted Scar when this is done. " },
