    { id = 7583, name = "Suppression", level = 60, minLevel = 60, requires = { 7581, 7582 }, giver = "Daio the Decrepit", start = { npc = "Daio the Decrepit", area = 4, x = 34.1, y = 50.1 }, finish = { npc = "Daio the Decrepit", area = 4, x = 34.1, y = 50.1 }, objective = "Venture forth into the Tainted Scar and locate a Doomguard Commander.  Use the Glowing Crystal Prison on the Doomguard Commander. Be prepared for a ferocious onslaught of attacks, as the demon attempts to escape capture.  Should you succeed, return the Imprisoned Doomguard to Daio in the Tainted Scar." },
    { id = 7601, name = "What Niby Commands", level = 50, minLevel = 50, giver = "Niby the Almighty", start = { npc = "Niby the Almighty", area = 361, x = 41.4, y = 44.9 }, finish = { npc = "Impsy", area = 361, x = 41.4, y = 45.0 }, objective = "Speak with Impsy in Felwood." },
    { id = 7602, name = "Flawless Fel Essence", level = 55, minLevel = 50, requires = { 7601 }, giver = "Impsy", start = { npc = "Impsy", area = 361, x = 41.4, y = 45.0 }, finish = { npc = "Impsy", area = 361, x = 41.4, y = 45.0 }, objective = "Impsy in Felwood has asked that you bring him three Flawless Fel Essences originating from three distinct locations.  The Legashi Satyrs of Azshara hold the Flawless Fel Essence of their region. The Jaedenar Legionnaires of Jaedenar hold the Flawless Fel Essence of their region. The Felguard Sentries of the Blasted Lands hold the Flawless Fel Essence of their region.  Recover the Flawless Fel Essences and return to Impsy in Felwood." },
    { id = 7603, name = "Kroshius' Infernal Core", level = 55, minLevel = 50, requires = { 7602 }, giver = "Impsy", start = { npc = "Impsy", area = 361, x = 41.4, y = 45.0 }, finish = { npc = "Niby the Almighty", area = 361, x = 41.4, y = 44.9 }, objective = "Search Shatter Scar Vale in Felwood for the remains of Kroshius. When you locate the remains, use the Fel Fire near them and await Kroshius' return. When the infernal has awoken, slay him and take from his corpse Kroshius' Infernal Core.  Return Kroshius' Infernal Core to Niby the Almighty in Felwood." },
